const AsteroidDescriptor = struct {
    name: []const u8,
    blueprint: []const u8,
    scoreTracker: ScoreTracker,
};

var allDescriptors: [allBlueprints.len]AsteroidDescriptor = init: {
    @setEvalBranchQuota(10000);
    var result: [allBlueprints.len]AsteroidDescriptor = undefined;
    for (allBlueprints, 0..) |bpRow, i| {
        result[i] = AsteroidDescriptor{
            .name = bpRow[0],
            .blueprint = bpRow[1],
            .scoreTracker = .{},
        };
    }

    // copy referenceSolutions into descriptors
    for (referenceSolutions, 0..) |refRow, i| {
        const name = refRow[0];
        const desc: *AsteroidDescriptor = &result[i];
        std.debug.assert(std.mem.eql(u8, name, desc.name));

        const container = &desc.scoreTracker.prevMetrics;
        const tInfo = @typeInfo(ScoreMetrics);
        for (tInfo.Struct.fields, 1..) |field, colIdx| {
            const ftInfo = @typeInfo(field.type);
            if (ftInfo == .Optional) {
                @field(container.*, field.name) = std.fmt.parseInt(ftInfo.Optional.child, refRow[colIdx], 10) catch unreachable;
            } else {
                @field(container.*, field.name) = std.fmt.parseInt(field.type, refRow[colIdx], 10) catch unreachable;
            }
        }
    }
    break :init result;
};

const ScoreTracker = struct {
    const Self = @This();
    prevMetrics: ScoreMetrics = .{},
    worseMetrics: ScoreMetrics = .{},
    betterMetrics: ScoreMetrics = .{},

    pub fn track(self: *Self, solution: ScoreMetrics) void {
        const tInfo = @typeInfo(ScoreMetrics);
        inline for (tInfo.Struct.fields) |field| {
            self.trackMetric(field.name, field.type, @field(solution, field.name));
        }
    }

    fn trackMetric(self: *Self, comptime metric: []const u8, comptime T: type, value: T) void {
        const metricEnum = comptime blk: {
            break :blk std.meta.stringToEnum(ScoreMetrics.Fields, metric) orelse unreachable;
        };
        const prev = @field(self.prevMetrics, metric);
        const comp = switch (metricEnum) {
            // more is better
            .numEdgeMiners => compare(T, value, prev),
            .numMiners => compare(T, value, prev),
            // less is better
            .numGaps => compare(T, prev, value),
            .numIslands => compare(T, prev, value),
            // less is better but with tolerance to reduce noise
            .p1Time => compareWithTolerance(T, prev, value, 150),
            .p2Time => compareWithTolerance(T, prev, value, 150),
            .p3Time => compareWithTolerance(T, prev, value, 150),
            .totalTime => compareWithTolerance(T, prev, value, 150),
        };
        if (comp < 0) {
            @field(self.worseMetrics, metric) = value;
        }
        if (comp > 0) {
            @field(self.betterMetrics, metric) = value;
        }
    }

    fn compare(comptime T: type, a: T, b: T) i2 {
        return compareWithTolerance(T, a, b, 0);
    }

    fn compareWithTolerance(comptime T: type, a: T, b: T, tolerance: T) i2 {
        const tInfo = @typeInfo(T);
        if (tInfo == .Optional) {
            if (a == null or b == null)
                return 0; // don't compare nulls. (should only occur when a new blueprint is added but no reference solution was generated yet)
            return compareWithTolerance(tInfo.Optional.child, a.?, b.?, tolerance.?);
        }

        // Note: avoid subtraction here because T can be unsigned.
        if ((a + tolerance) < b) {
            return -1;
        } else if (a > (b + tolerance)) {
            return 1;
        } else {
            return 0;
        }
    }
};

const ScoreMetrics = struct {
    pub const Fields = enum {
        numEdgeMiners,
        numMiners,
        numGaps,
        numIslands,
        p1Time,
        p2Time,
        p3Time,
        totalTime,
    };

    numEdgeMiners: ?usize = null,
    numMiners: ?usize = null,
    numGaps: ?usize = null,
    numIslands: ?usize = null,
    p1Time: ?i64 = null,
    p2Time: ?i64 = null,
    p3Time: ?i64 = null,
    totalTime: ?i64 = null,
};

fn checkMemoryUsage(alloc: *std.heap.ArenaAllocator) usize {
    const curNode = alloc.state.buffer_list.first;
    if (curNode == null)
        return 0;

    var prevNode = curNode.?.next;
    var nodeBytes: usize = 0;
    while (prevNode) |node| {
        nodeBytes += node.data; // data is length of the buffer
        prevNode = node.next;
    }

    return nodeBytes + alloc.state.end_index;
}

test "evaluate solver on all sample asteroids" {
    const singleRoid: ?[]const u8 = null;
    const ErrorHandler = struct {
        const Self = @This();
        fn onWarn(_: *anyopaque, _: []const u8) void {}
        fn onError(_: *anyopaque, _: []const u8) void {}
    };

    var handlerInstance = ErrorHandler{};
    var problemCallback: ProblemCallback = .{
        .ctx = &handlerInstance,
        .onWarn = ErrorHandler.onWarn,
        .onError = ErrorHandler.onError,
    };
    const p1Opts: solver.Phase1Options = .{};
    const p2Opts: solver.Phase2Options = .{};
    const p3Opts: solver.Phase3Options = .{};

    var arenaAlloc = std.heap.ArenaAllocator.init(std.testing.allocator);
    const alloc = arenaAlloc.allocator();
    defer arenaAlloc.deinit();

    var scores: [allDescriptors.len]ScoreMetrics = undefined;
    for (&allDescriptors, 0..) |*desc, i| {
        scores[i] = .{
            .numEdgeMiners = null,
            .numMiners = null,
            .numGaps = null,
            .numIslands = null,
            .p1Time = null,
            .p2Time = null,
            .p3Time = null,
            .totalTime = null,
        };

        if (singleRoid != null and !std.mem.eql(u8, singleRoid.?, desc.name))
            continue;

        _ = arenaAlloc.reset(.retain_capacity);

        var asteroids = std.ArrayList(asteroid.Asteroid).init(alloc);
        const pInitialBytes = checkMemoryUsage(&arenaAlloc);
        _ = try bpParser.parseRoidMask(desc.blueprint, alloc, &.{}, &problemCallback, &asteroids);
        const pFinalBytes = checkMemoryUsage(&arenaAlloc);

        for (asteroids.items, 0..) |*roid, rId| {
            const initialBytes = checkMemoryUsage(&arenaAlloc);
            const startTime = std.time.milliTimestamp();
            const p0: *solver.Phase0Data = try solver.phase0(alloc, roid, &problemCallback);
            const p1Begin = std.time.milliTimestamp();
            const p1: *solver.Phase1Data = try solver.phase1(alloc, roid, p0, &p1Opts);
            const p2Begin = std.time.milliTimestamp();
            const p2: *solver.Phase2Data = try solver.phase2(alloc, roid, p0, p1, &p2Opts);
            const p3Begin = std.time.milliTimestamp();
            const p3: *solver.Phase3Data = try solver.phase3(alloc, roid, p0, &p3Opts);
            const endTime = std.time.milliTimestamp();
            const finalBytes = checkMemoryUsage(&arenaAlloc);

            const solverStats = solver.calcStats(p0, p1, p2, p3);
            const numMinersTotal: i32 = solverStats.numEdgeMiners + (solverStats.numCenterMiners * 3);
            const expectedNumOccupied: i32 = @intCast(p0.occupancy.count());
            const actualNumOccupied = (solverStats.numEdgeMiners * 4) + (solverStats.numCenterMiners * 14);
            try std.testing.expectEqual(expectedNumOccupied, actualNumOccupied);

            scores[i].numEdgeMiners = (scores[i].numEdgeMiners orelse 0) + @as(u32, @intCast(solverStats.numEdgeMiners));
            scores[i].numMiners = (scores[i].numMiners orelse 0) + @as(u32, @intCast(numMinersTotal));
            scores[i].numGaps = (scores[i].numGaps orelse 0) + @as(u32, @intCast(solverStats.gapTiles));
            scores[i].numIslands = (scores[i].numIslands orelse 0) + @as(u32, @intCast(solverStats.gapIslands));
            scores[i].p1Time = (scores[i].p1Time orelse 0) + (p2Begin - p1Begin);
            scores[i].p2Time = (scores[i].p2Time orelse 0) + (p3Begin - p2Begin);
            scores[i].p3Time = (scores[i].p3Time orelse 0) + (endTime - p3Begin);
            scores[i].totalTime = (scores[i].totalTime orelse 0) + (endTime - startTime);

            if (saveDebugImages) {
                const img = try renderer.render(alloc, roid, p0, p1);
                const outFileNoExt = try std.fmt.allocPrint(alloc, "zig-out/img/{}_{s}.{}.p1", .{ i, desc.name, rId });
                try renderer.writeToFile(alloc, img, outFileNoExt);

                const imgP2 = try renderer.renderP2(alloc, roid, p0, p1, p2);
                const outFileNoExtP2 = try std.fmt.allocPrint(alloc, "zig-out/img/{}_{s}.{}.p2", .{ i, desc.name, rId });
                try renderer.writeToFile(alloc, imgP2, outFileNoExtP2);

                const imgP3 = try renderer.renderP3(alloc, roid, p0, p1, p2, p3);
                const outFileNoExtP3 = try std.fmt.allocPrint(alloc, "zig-out/img/{}_{s}.{}.p3", .{ i, desc.name, rId });
                try renderer.writeToFile(alloc, imgP3, outFileNoExtP3);
            }

            // verify that resolving rotations and serializing at least does not crash
            const rots = try solver.findRotations(alloc, roid, p0, p1, p2, p3);
            const minerContentRotations = .{dt.BuildingBlueprint{.Entries = &.{}}} ** dt.Rotation.numRotations;
            const solutionBp = try bpWriter.solverSolutionToBlueprint(alloc, roid, p0, p1, p2, p3, rots, &minerContentRotations);
            _ = try bpWriter.encodeBlueprint(alloc, solutionBp, ._5);

            const numParserAlloc: u64 = @intCast(pFinalBytes - pInitialBytes);
            const numSolverAlloc: u64 = @intCast(finalBytes - initialBytes);
            std.debug.print("{s}.{} allocated memory: (parser={B}, solver={B})\n", .{
                desc.name,
                rId,
                std.fmt.fmtIntSizeDec(numParserAlloc),
                std.fmt.fmtIntSizeDec(numSolverAlloc),
            });
        }
        desc.scoreTracker.track(scores[i]);
    }

    const ftInfo = @typeInfo(ScoreMetrics.Fields);
    for (&scores, &allDescriptors) |*score, *desc| {
        std.debug.print("  .{{ ", .{});
        std.debug.print("\"{s}\"", .{desc.name});
        inline for (ftInfo.Enum.fields) |field| {
            std.debug.print(", \"{}\"", .{@field(score, field.name) orelse 0});
        }
        std.debug.print(" }},\n", .{});
    }

    var anyWorse = false;
    var anyBetter = false;
    for (&allDescriptors) |*desc| {
        inline for (ftInfo.Enum.fields) |field| {
            if (@field(desc.scoreTracker.worseMetrics, field.name)) |_| {
                anyWorse = true;
            }
            if (@field(desc.scoreTracker.betterMetrics, field.name)) |_| {
                anyBetter = true;
            }
        }
    }
    if (anyWorse) {
        std.debug.print("WORSE:\n", .{});
        inline for (ftInfo.Enum.fields) |field| {
            for (&allDescriptors) |*desc| {
                if (@field(desc.scoreTracker.worseMetrics, field.name)) |value| {
                    const prevValue = @field(desc.scoreTracker.prevMetrics, field.name).?;
                    std.debug.print("  {s} {s} : {} -> {}\n", .{ field.name, desc.name, prevValue, value });
                }
            }
        }
    }
    if (anyBetter) {
        std.debug.print("BETTER:\n", .{});
        inline for (ftInfo.Enum.fields) |field| {
            for (&allDescriptors) |*desc| {
                if (@field(desc.scoreTracker.betterMetrics, field.name)) |value| {
                    const prevValue = @field(desc.scoreTracker.prevMetrics, field.name).?;
                    std.debug.print("  {s} {s} : {} -> {}\n", .{ field.name, desc.name, prevValue, value });
                }
            }
        }
    }
}
